-- ============================================================
-- WorkOS 桌面 SQLite 初始结构；时间点统一为 UTC epoch 毫秒
--
-- 统一规范：
--   表名        无前缀
--   时间点      INTEGER（Java Instant）
--   日期        DATE（Java LocalDate）
--   主键        BIGINT GENERATED BY DEFAULT AS IDENTITY
--   乐观锁      version
-- ============================================================



-- ------------------------------------------------------------
-- project
-- ------------------------------------------------------------
CREATE TABLE project (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    name         VARCHAR(200) NOT NULL,
    code         VARCHAR(100),
    description  TEXT,
    status       VARCHAR(30) NOT NULL DEFAULT 'ACTIVE',
    color        VARCHAR(20),
    sort_order   INTEGER NOT NULL DEFAULT 0,
    created_at   INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER) * 1000),
    updated_at   INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER) * 1000),
    archived_at  INTEGER,
    version      INTEGER NOT NULL DEFAULT 0,
    CONSTRAINT uk_project_code UNIQUE (code)
);

-- ------------------------------------------------------------
-- project_context
--   稳定信息：goal / key_people / key_links
--   动态状态：focus / blocker / next_action / progress_note（可选）
-- ------------------------------------------------------------
CREATE TABLE project_context (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id   BIGINT NOT NULL,
    goal         TEXT,
    key_people   TEXT,
    key_links    TEXT,
    focus        TEXT,
    blocker      TEXT,
    next_action  TEXT,
    progress_note TEXT,
    notes_markdown TEXT,
    updated_at   INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER) * 1000),
    version      INTEGER NOT NULL DEFAULT 0,
    CONSTRAINT uk_project_context_project UNIQUE (project_id),
    CONSTRAINT fk_project_context_project
        FOREIGN KEY (project_id) REFERENCES project(id) ON DELETE CASCADE
);

-- ------------------------------------------------------------
-- item
--   类型只有 TASK / NOTE；Follow-up 是能力（next_follow_up_at 非空）
--   没有 parent_id、没有 related_company、没有 source
-- ------------------------------------------------------------
CREATE TABLE item (
    id                  INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id          BIGINT,
    title               VARCHAR(500) NOT NULL,
    description         TEXT,
    item_type           VARCHAR(30) NOT NULL DEFAULT 'TASK',
    status              VARCHAR(30) NOT NULL DEFAULT 'INBOX',
    priority            VARCHAR(10) NOT NULL DEFAULT 'P2',
    planned_date        DATE,
    plan_rank           INTEGER,
    due_at              INTEGER,
    next_follow_up_at   INTEGER,
    waiting_for         VARCHAR(200),
    waiting_since       INTEGER,
    waiting_expected_at INTEGER,
    related_person      VARCHAR(200),
    completed_at        INTEGER,
    cancelled_at        INTEGER,
    source              VARCHAR(30) NOT NULL DEFAULT 'MANUAL',
    created_at          INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER) * 1000),
    updated_at          INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER) * 1000),
    version             INTEGER NOT NULL DEFAULT 0,
    CONSTRAINT fk_item_project
        FOREIGN KEY (project_id) REFERENCES project(id) ON DELETE SET NULL
);

-- ------------------------------------------------------------
-- work_log（只有人工记录，没有 source）
-- ------------------------------------------------------------
CREATE TABLE work_log (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id  BIGINT,
    item_id     BIGINT,
    work_date   DATE NOT NULL,
    occurred_at INTEGER NOT NULL,
    content     TEXT NOT NULL,
    created_at  INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER) * 1000),
    updated_at  INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER) * 1000),
    CONSTRAINT fk_work_log_project
        FOREIGN KEY (project_id) REFERENCES project(id) ON DELETE SET NULL,
    CONSTRAINT fk_work_log_item
        FOREIGN KEY (item_id) REFERENCES item(id) ON DELETE SET NULL
);

-- ------------------------------------------------------------
-- item_activity（系统事件，不进日报"工作内容"）
-- ------------------------------------------------------------
CREATE TABLE item_activity (
    id            INTEGER PRIMARY KEY AUTOINCREMENT,
    item_id       BIGINT NOT NULL,
    activity_type VARCHAR(30) NOT NULL,
    from_status   VARCHAR(30),
    to_status     VARCHAR(30),
    field_name    VARCHAR(50),
    old_value     TEXT,
    new_value     TEXT,
    remark        TEXT,
    actor         VARCHAR(20) NOT NULL DEFAULT 'SYSTEM',
    occurred_at   INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER) * 1000),
    CONSTRAINT fk_item_activity_item
        FOREIGN KEY (item_id) REFERENCES item(id) ON DELETE CASCADE
);

-- ------------------------------------------------------------
-- daily
-- ------------------------------------------------------------
CREATE TABLE daily (
    id                INTEGER PRIMARY KEY AUTOINCREMENT,
    daily_date        DATE NOT NULL,
    content           TEXT,
    generated_content TEXT,
    status            VARCHAR(20) NOT NULL DEFAULT 'DRAFT',
    created_at        INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER) * 1000),
    updated_at        INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER) * 1000),
    version           INTEGER NOT NULL DEFAULT 0,
    CONSTRAINT uk_daily_date UNIQUE (daily_date)
);

-- ------------------------------------------------------------
-- reminder（PENDING / DISMISSED / CANCELLED，没有 FIRED）
-- ------------------------------------------------------------
CREATE TABLE reminder (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    kind            VARCHAR(20) NOT NULL DEFAULT 'ITEM',
    item_id         BIGINT,
    title           VARCHAR(500) NOT NULL,
    remind_at       INTEGER NOT NULL,
    status          VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    triggered_at    INTEGER,
    acknowledged_at INTEGER,
    created_at      INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER) * 1000),
    CONSTRAINT fk_reminder_item
        FOREIGN KEY (item_id) REFERENCES item(id) ON DELETE CASCADE
);

-- ------------------------------------------------------------
-- settings（单行；"今天"的唯一真源）
--   day_boundary_hour 默认 0：MVP 固定自然日，不进界面
-- ------------------------------------------------------------
CREATE TABLE settings (
    id                     SMALLINT PRIMARY KEY DEFAULT 1,
    timezone               VARCHAR(50) NOT NULL DEFAULT 'Asia/Shanghai',
    date_format            VARCHAR(20) NOT NULL DEFAULT 'YYYY-MM-DD',
    week_start             VARCHAR(10) NOT NULL DEFAULT 'MONDAY',
    day_boundary_hour      SMALLINT NOT NULL DEFAULT 0,
    morning_brief_time     VARCHAR(5) NOT NULL DEFAULT '09:00',
    eod_review_time        VARCHAR(5) NOT NULL DEFAULT '18:00',
    desktop_notification   BOOLEAN NOT NULL DEFAULT TRUE,
    quick_capture_shortcut VARCHAR(50) NOT NULL DEFAULT 'Alt+Space',
    updated_at             INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER) * 1000),
    CONSTRAINT uk_settings_single_row CHECK (id = 1)
);

INSERT INTO settings (id) VALUES (1) ON CONFLICT (id) DO NOTHING;

-- ------------------------------------------------------------
-- account（单用户最小身份）
-- ------------------------------------------------------------
CREATE TABLE account (
    id            INTEGER PRIMARY KEY AUTOINCREMENT,
    username      VARCHAR(100) NOT NULL,
    password_hash VARCHAR(200) NOT NULL,
    created_at    INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER) * 1000),
    updated_at    INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER) * 1000),
    CONSTRAINT uk_account_username UNIQUE (username)
);

-- ------------------------------------------------------------
-- 索引
-- ------------------------------------------------------------
CREATE INDEX idx_project_status ON project (status);
CREATE INDEX idx_project_sort ON project (sort_order);

CREATE INDEX idx_item_project ON item (project_id);
CREATE INDEX idx_item_status ON item (status);
CREATE INDEX idx_item_priority ON item (priority);
CREATE INDEX idx_item_due ON item (due_at);
CREATE INDEX idx_item_follow_up ON item (next_follow_up_at);
CREATE INDEX idx_item_project_status ON item (project_id, status);
CREATE INDEX idx_item_status_priority ON item (status, priority);
CREATE INDEX idx_item_planned_date ON item (planned_date, plan_rank);
CREATE INDEX idx_item_unclassified ON item (status) WHERE project_id IS NULL;






CREATE INDEX idx_work_log_date ON work_log (work_date);
CREATE INDEX idx_work_log_project_date ON work_log (project_id, work_date);
CREATE INDEX idx_item_activity_item_time ON item_activity (item_id, occurred_at DESC);

CREATE INDEX idx_reminder_pending ON reminder (status, remind_at);

-- 可重复执行；既有 item.project_id 保留为主项目，不改动现有记录。
CREATE TABLE IF NOT EXISTS item_project_link (
    item_id BIGINT NOT NULL REFERENCES item(id) ON DELETE CASCADE,
    project_id BIGINT NOT NULL REFERENCES project(id) ON DELETE CASCADE,
    PRIMARY KEY (item_id, project_id)
);
CREATE INDEX IF NOT EXISTS idx_item_project_link_project ON item_project_link(project_id, item_id);
